import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ---------- Kernel source for naive matrix multiplication (C = A^T @ B^T) ----------
matmul_kernel_source = """
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Each thread computes one output element: C[i * N + j]
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= M * N) return;

    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        // A is stored as [K][M]; element A[k, i] -> index a_idx = k * M + i
        int a_idx = k * M + i;
        if (a_idx < K * M) {
            sum += A[a_idx];
        }
        // B is stored as [N][K]; element B[j, k] -> index b_idx = j * K + k.
        // Here j corresponds to column of C: j = i % N
        int j = i % N;
        int b_idx = j * K + k;
        if (b_idx < N * K) {
            sum += B[b_idx];
        }
    }
    C[i] = sum;
}
"""

matmul_cuda_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Input shapes: A (K, M), B (N, K)
    int M = A.size(1);
    int K = A.size(0);
    int N = B.size(0);

    auto out = torch::zeros(M, N, memory_layout(a));  // placeholder allocation

    const int block_size = 256;
    const int num_blocks_rows = (M + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks_rows, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), out.data_ptr<float()>, M, K, N);

    return out;
}
"""

# Compile the custom CUDA kernel for matrix multiplication
matmul = load_inline(
    name="matmul_cuda",
    cpp_sources=matmul_kernel_source,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Original model: return torch.matmul(A.T, B.T)
        Our custom implementation computes C = (A^T @ B^T).
        Therefore we pass the transposed inputs to our kernel.
        """
        # A is (K, M), B is (N, K).  We need result shape (M, N).
        return self.matmul_cuda(A.T, B.T)
